//! The sfnt and PNG writer the committed bitmap fixtures are generated by:
//! `sbix-strikes.ttf` and the Adam7 PNGs (`bitmap.rs`) and
//! `cblc-cases.ttf` (`cblc.rs`).
//!
//! **Every byte is generated but the zlib streams.** A PNG's `IDAT` payload
//! is a deflate of rows the generator computes, and which bytes a deflate
//! writes is the compressor's choice, not the format's: the committed
//! streams are zlib 1.3.1's at level 9. So the payloads are taken from the
//! committed file and held to the rows instead -- [`Payloads`] maps each
//! committed stream by what it inflates to, and the generator asks it for
//! the stream of its own rows. A row that changes finds no stream, and the
//! whole file is then compared byte for byte, so every offset, length, CRC
//! and checksum around the payloads is the generator's.

// Each test that includes this module uses its own part of it.
#![allow(dead_code)]

use std::cell::Cell;
use std::collections::HashMap;

pub const SIGNATURE: &[u8; 8] = b"\x89PNG\r\n\x1a\n";

/// The committed zlib streams, by the rows each inflates to.
pub struct Payloads {
    streams: HashMap<Vec<u8>, Vec<u8>>,
    /// Streams that do not inflate, in the order they were found.
    pub invalid: Vec<Vec<u8>>,
    /// Streams that do, counted with repeats.
    pub valid: usize,
    missed: Cell<usize>,
    asked: Cell<usize>,
    perturb: Option<usize>,
}

impl Payloads {
    pub fn new() -> Self {
        Self {
            streams: HashMap::new(),
            invalid: Vec::new(),
            valid: 0,
            missed: Cell::new(0),
            asked: Cell::new(0),
            perturb: None,
        }
    }

    /// Every PNG in `bytes`, found by its signature and walked by its
    /// chunks: the payload is its `IDAT` bodies joined (11.2.4).
    pub fn add(&mut self, bytes: &[u8]) {
        let mut from = 0;
        while let Some(at) = find(&bytes[from..], SIGNATURE) {
            let mut j = from + at + 8;
            let mut z = Vec::new();
            loop {
                let n = usize::try_from(u32::from_be_bytes(bytes[j..j + 4].try_into().unwrap()))
                    .unwrap();
                let kind = &bytes[j + 4..j + 8];
                if kind == b"IDAT" {
                    z.extend_from_slice(&bytes[j + 8..j + 8 + n]);
                }
                j += 12 + n;
                if kind == b"IEND" {
                    break;
                }
            }
            match miniz_oxide::inflate::decompress_to_vec_zlib(&z) {
                Ok(rows) => {
                    self.valid += 1;
                    self.streams.insert(rows, z);
                }
                Err(_) => self.invalid.push(z),
            }
            from = j;
        }
    }

    /// The same streams, with the `k`th row buffer the generator asks for
    /// changed in its last byte: the positive control for [`Self::deflate`].
    pub fn perturbing(mut self, k: usize) -> Self {
        self.perturb = Some(k);
        self
    }

    /// The committed stream that inflates to `rows`. A miss is counted and
    /// answered with miniz_oxide's deflate, so the file still assembles --
    /// a candidate to commit if the change was meant.
    pub fn deflate(&self, rows: &[u8]) -> Vec<u8> {
        let k = self.asked.get();
        self.asked.set(k + 1);
        let mut rows = rows.to_vec();
        if self.perturb == Some(k) {
            *rows.last_mut().unwrap() ^= 1;
        }
        match self.streams.get(&rows) {
            Some(z) => z.clone(),
            None => {
                self.missed.set(self.missed.get() + 1);
                miniz_oxide::deflate::compress_to_vec_zlib(&rows, 10)
            }
        }
    }

    /// Row buffers no committed stream inflates to.
    pub fn missed(&self) -> usize {
        self.missed.get()
    }
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    hay.windows(needle.len()).position(|w| w == needle)
}

/// Holds a generated file to the committed one. On a difference the fresh
/// bytes are written beside the temporary directory's other files, to be
/// copied over the fixture (and re-pinned) if the change was meant.
pub fn assert_written(name: &str, fresh: &[u8], committed: &[u8], z: &Payloads) {
    if fresh == committed && z.missed() == 0 {
        return;
    }
    let out = std::env::temp_dir().join(format!("baud-{}-{name}", std::process::id()));
    std::fs::write(&out, fresh).unwrap();
    panic!(
        "{name} is not what its generator writes ({} row buffer(s) match no committed \
         stream; first difference at byte {:?}); the generator's file is {}",
        z.missed(),
        fresh.iter().zip(committed).position(|(a, b)| a != b),
        out.display()
    );
}

/// The CRC-32 of ISO 3309 that PNG's chunks carry (5.5).
pub fn crc32(data: &[u8]) -> u32 {
    let mut c = 0xFFFF_FFFFu32;
    for &b in data {
        c ^= u32::from(b);
        for _ in 0..8 {
            c = if c & 1 != 0 {
                0xEDB8_8320 ^ (c >> 1)
            } else {
                c >> 1
            };
        }
    }
    !c
}

/// One PNG chunk: length, type, data, CRC over type and data (5.3).
pub fn chunk(kind: &[u8; 4], data: &[u8]) -> Vec<u8> {
    let mut body = kind.to_vec();
    body.extend_from_slice(data);
    let mut out = Be::default().n32(data.len()).done();
    out.extend_from_slice(&body);
    out.extend_from_slice(&crc32(&body).to_be_bytes());
    out
}

/// A `ppem` square of 8-bit RGBA whose zlib stream is `idat`.
pub fn png_rgba8(ppem: u32, idat: &[u8]) -> Vec<u8> {
    let mut ihdr = ppem.to_be_bytes().to_vec();
    ihdr.extend_from_slice(&ppem.to_be_bytes());
    ihdr.extend_from_slice(&[8, 6, 0, 0, 0]);
    let mut out = SIGNATURE.to_vec();
    out.extend(chunk(b"IHDR", &ihdr));
    out.extend(chunk(b"IDAT", idat));
    out.extend(chunk(b"IEND", b""));
    out
}

/// Rows of a `ppem` square whose left half is `colour` and right half
/// `white`, each row behind filter byte 0.
pub fn halves(ppem: u32, colour: [u8; 3], white: [u8; 3]) -> Vec<u8> {
    let half = ppem / 2;
    let mut row = vec![0];
    for x in 0..ppem {
        let [r, g, b] = if x < half { colour } else { white };
        row.extend_from_slice(&[r, g, b, 255]);
    }
    row.repeat(usize::try_from(ppem).unwrap())
}

/// A big-endian byte writer, `struct.pack(">...")`'s counterpart.
#[derive(Default)]
pub struct Be(pub Vec<u8>);

impl Be {
    pub fn u8(&mut self, v: u8) -> &mut Self {
        self.0.push(v);
        self
    }
    pub fn i8(&mut self, v: i8) -> &mut Self {
        self.0.extend_from_slice(&v.to_be_bytes());
        self
    }
    pub fn u16(&mut self, v: u16) -> &mut Self {
        self.0.extend_from_slice(&v.to_be_bytes());
        self
    }
    pub fn i16(&mut self, v: i16) -> &mut Self {
        self.0.extend_from_slice(&v.to_be_bytes());
        self
    }
    pub fn u32(&mut self, v: u32) -> &mut Self {
        self.0.extend_from_slice(&v.to_be_bytes());
        self
    }
    pub fn i64(&mut self, v: i64) -> &mut Self {
        self.0.extend_from_slice(&v.to_be_bytes());
        self
    }
    /// A length or offset, which a fixture never takes past 16 bits.
    pub fn n16<N: TryInto<u16, Error: std::fmt::Debug>>(&mut self, n: N) -> &mut Self {
        self.u16(n.try_into().expect("a 16-bit length"))
    }
    /// A length or offset, which a fixture never takes past 32 bits.
    pub fn n32<N: TryInto<u32, Error: std::fmt::Debug>>(&mut self, n: N) -> &mut Self {
        self.u32(n.try_into().expect("a 32-bit length"))
    }
    pub fn bytes(&mut self, v: &[u8]) -> &mut Self {
        self.0.extend_from_slice(v);
        self
    }
    pub fn done(&mut self) -> Vec<u8> {
        std::mem::take(&mut self.0)
    }
}

/// The units per em both bitmap fixtures are written at.
pub const UPEM: u16 = 800;

pub fn head() -> Vec<u8> {
    Be::default()
        .u32(0x0001_0000)
        .u32(0x0001_0000)
        .u32(0)
        .u32(0x5F0F_3CF5)
        .u16(0)
        .u16(UPEM)
        .i64(0)
        .i64(0)
        .i16(0)
        .i16(-200)
        .i16(i16::try_from(UPEM).unwrap())
        .i16(800)
        .u16(0)
        .u16(8)
        .i16(2)
        .i16(0)
        .i16(0)
        .done()
}

pub fn hhea(glyphs: u16) -> Vec<u8> {
    let mut b = Be::default();
    b.u32(0x0001_0000)
        .i16(800)
        .i16(-200)
        .i16(0)
        .u16(UPEM)
        .i16(0)
        .i16(0)
        .i16(i16::try_from(UPEM).unwrap())
        .i16(1);
    for _ in 0..7 {
        b.i16(0);
    }
    b.u16(glyphs).done()
}

pub fn maxp(glyphs: u16) -> Vec<u8> {
    Be::default().u32(0x0000_5000).u16(glyphs).done()
}

pub fn hmtx(glyphs: u16) -> Vec<u8> {
    let mut b = Be::default();
    for _ in 0..glyphs {
        b.u16(UPEM).i16(0);
    }
    b.done()
}

/// One format 12 subtable, platform 3 encoding 10, over `groups` of
/// (first code point, last code point, first glyph).
pub fn cmap(groups: &[(u32, u32, u32)]) -> Vec<u8> {
    let n = groups.len();
    let mut b = Be::default();
    b.u16(0).u16(1).u16(3).u16(10).u32(12);
    b.u16(12).u16(0).n32(16 + 12 * n).u32(0).n32(n);
    for &(s, e, g) in groups {
        b.u32(s).u32(e).u32(g);
    }
    b.done()
}

/// `post` version 3: no glyph names.
pub fn post() -> Vec<u8> {
    let mut b = Be::default();
    b.u32(0x0003_0000).u32(0).i16(0).i16(0).u32(1);
    for _ in 0..4 {
        b.u32(0);
    }
    b.done()
}

/// The sum of a table's big-endian words, zero-padded to a word.
pub fn checksum(data: &[u8]) -> u32 {
    data.chunks(4)
        .map(|c| {
            let mut w = [0u8; 4];
            w[..c.len()].copy_from_slice(c);
            u32::from_be_bytes(w)
        })
        .fold(0u32, u32::wrapping_add)
}

/// An sfnt of `tables`, directory sorted by tag, each table padded to a
/// word, and `head`'s `checksumAdjustment` set so the whole file sums to
/// `0xB1B0AFBA`.
pub fn sfnt(mut tables: Vec<([u8; 4], Vec<u8>)>) -> Vec<u8> {
    tables.sort_by_key(|t| t.0);
    let n = u16::try_from(tables.len()).unwrap();
    let mut search = 1u16;
    while search * 2 <= n {
        search *= 2;
    }
    let selector = u16::try_from(search.ilog2()).unwrap();
    let mut out = Be::default();
    out.u32(0x0001_0000)
        .u16(n)
        .u16(search * 16)
        .u16(selector)
        .u16(n * 16 - search * 16);
    let directory = 12 + 16 * usize::from(n);
    let mut body = Vec::new();
    let mut head_at = None;
    for (tag, data) in &tables {
        let at = directory + body.len();
        if tag == b"head" {
            head_at = Some(at);
        }
        out.bytes(tag).u32(checksum(data)).n32(at).n32(data.len());
        body.extend_from_slice(data);
        body.resize(body.len().next_multiple_of(4), 0);
    }
    let mut whole = out.done();
    whole.extend(body);
    let adjust = 0xB1B0_AFBAu32.wrapping_sub(checksum(&whole));
    let h = head_at.expect("a head table");
    whole[h + 8..h + 12].copy_from_slice(&adjust.to_be_bytes());
    whole
}
